import{_ as e,c as t,o as a,a2 as r}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"StepperHeader","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Stepper Header"},"headers":[],"relativePath":"guide/components/stepper/stepper-header.md","filePath":"guide/components/stepper/stepper-header.md","lastUpdated":1777448653000}'),d={name:"guide/components/stepper/stepper-header.md"},o=r('<h1 id="stepperheader" tabindex="-1">StepperHeader <a class="header-anchor" href="#stepperheader" aria-label="Permalink to &quot;StepperHeader&quot;">​</a></h1><p><code>StepperHeader</code> renders the horizontal step indicator bar at the top of the stepper. It displays one item per form step plus a final <strong>Preview &amp; Summary</strong> item. Completed steps show a checkmark and are clickable to navigate back.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is an internal sub-component of <code>ue-stepper-form</code>. You do not use it directly.</p></div><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li>Each step item shows its <code>title</code> from the <code>forms</code> array.</li><li>A step is marked <strong>complete</strong> when <code>activeStep</code> is greater than that step&#39;s index.</li><li>Clicking a completed step&#39;s title emits <code>step-click</code> with the 1-based step number. The parent (<code>StepperForm</code>) only allows backward navigation — forward jumps to incomplete steps are blocked.</li><li>The final <strong>Preview &amp; Summary</strong> item is always the last entry and has no click handler.</li></ul><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table><thead><tr><th>Prop</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>forms</code></td><td><code>Array</code></td><td>Yes</td><td>The same <code>forms</code> array passed to <code>ue-stepper-form</code>. Each entry must have a <code>title</code>.</td></tr><tr><td><code>activeStep</code></td><td><code>Number</code></td><td>Yes</td><td>The currently active 1-based step index.</td></tr></tbody></table><h2 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h2><table><thead><tr><th>Event</th><th>Payload</th><th>Description</th></tr></thead><tbody><tr><td><code>step-click</code></td><td><code>Number</code></td><td>1-based index of the step the user clicked. Only emitted for completed steps (backward navigation).</td></tr></tbody></table><h2 id="visual-states" tabindex="-1">Visual States <a class="header-anchor" href="#visual-states" aria-label="Permalink to &quot;Visual States&quot;">​</a></h2><table><thead><tr><th>Condition</th><th>Appearance</th></tr></thead><tbody><tr><td><code>activeStep &gt; i+1</code></td><td>Step is complete — checkmark icon, title highlighted in primary colour</td></tr><tr><td><code>activeStep === i+1</code></td><td>Step is active — title highlighted in primary colour, bold</td></tr><tr><td><code>activeStep &lt; i+1</code></td><td>Step is upcoming — default muted appearance</td></tr></tbody></table>',11),i=[o];function s(c,p,l,h,n,m){return a(),t("div",null,i)}const f=e(d,[["render",s]]);export{b as __pageData,f as default};
